import assert from 'node:assert/strict'
import { spawn } from 'node:child_process'
import { existsSync, mkdirSync, rmSync, writeFileSync } from 'node:fs'

const BASE=process.env.QA_BASE??'https://osrm.github.io/catfood_web/'
const OUT='qa-artifacts', STORAGE='catfood.switch-session.v1', q=JSON.stringify
const CURRENT={productId:'product_d99406c26240b263',variantId:'variant_6e426a0abf2e1a43'}
const FIRST={productId:'product_c277594a66531d32',brand:'Advance',name:'어드밴스 캣 센시티브'}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));mkdirSync(OUT,{recursive:true})

class CDP{
  constructor(url){this.url=url;this.ws=null;this.id=1;this.pending=new Map();this.requests=[]}
  async connect(){this.ws=new WebSocket(this.url);await new Promise((r,j)=>{const t=setTimeout(()=>j(new Error('ws timeout')),15000);this.ws.addEventListener('open',()=>{clearTimeout(t);r()},{once:true});this.ws.addEventListener('error',j,{once:true})});this.ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.method==='Network.requestWillBeSent')this.requests.push({url:m.params.request.url,method:m.params.request.method});if(!m.id)return;const p=this.pending.get(m.id);if(!p)return;this.pending.delete(m.id);m.error?p.j(new Error(m.error.message)):p.r(m.result)});for(const x of ['Page.enable','Runtime.enable','Network.enable'])await this.send(x);await this.send('Page.addScriptToEvaluateOnNewDocument',{source:`(()=>{const f=window.fetch.bind(window);window.__qaBlocked={analytics:0,writes:0};window.fetch=(input,init={})=>{const u=typeof input==='string'?input:(input&&input.url)||'',m=String(init.method||(input&&input.method)||'GET').toUpperCase();if(u.includes('/functions/v1/decision-intake')){window.__qaBlocked.analytics++;return Promise.reject(new TypeError('blocked analytics'))}if(u.includes('gnosbstdatkytsyxuapt.supabase.co')&&!['GET','HEAD','OPTIONS'].includes(m)){window.__qaBlocked.writes++;return Promise.reject(new TypeError('blocked write'))}return f(input,init)}})();`})}
  send(method,params={}){const id=this.id++;return new Promise((r,j)=>{this.pending.set(id,{r,j});this.ws.send(JSON.stringify({id,method,params}))})}
  async eval(x){const r=await this.send('Runtime.evaluate',{expression:x,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.exception?.description??r.exceptionDetails.text);return r.result?.value}
  async wait(x,label,ms=40000){const end=Date.now()+ms;while(Date.now()<end){if(await this.eval(`Boolean(${x})`).catch(()=>false))return;await sleep(100)}throw new Error(`timeout ${label}`)}
  async nav(url){await this.send('Page.navigate',{url});await this.wait(`document.readyState==='complete'`,'ready');await this.wait(`document.querySelector('#root')&&document.body.innerText.length`,'root');await this.eval('document.fonts?.ready');await sleep(250)}
  async shot(name){const r=await this.send('Page.captureScreenshot',{format:'png',fromSurface:true,captureBeyondViewport:false});writeFileSync(`${OUT}/${name}`,Buffer.from(r.data,'base64'))}
  close(){try{this.ws?.close()}catch{}}
}
async function launch(){const chrome='/usr/bin/google-chrome';assert.ok(existsSync(chrome));const port=15700+(process.pid%150),dir=`/tmp/pr39-loadmore-${process.pid}`;rmSync(dir,{recursive:true,force:true});const proc=spawn(chrome,['--headless=new','--no-sandbox','--disable-dev-shm-usage','--disable-gpu','--disable-cache',`--remote-debugging-port=${port}`,`--user-data-dir=${dir}`,'about:blank'],{stdio:'ignore'});for(let i=0;i<200;i++){try{const pages=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json(),p=pages.find(x=>x.type==='page'&&x.webSocketDebuggerUrl);if(!p)throw 0;const c=new CDP(p.webSocketDebuggerUrl);await c.connect();await c.send('Emulation.setDeviceMetricsOverride',{width:390,height:900,deviceScaleFactor:1,mobile:true,screenWidth:390,screenHeight:900});return{c,proc,dir}}catch{}await sleep(100)}throw new Error('chrome timeout')}
async function cleanup(h){h.c.close();h.proc.kill('SIGTERM');await sleep(100);if(h.proc.exitCode==null)h.proc.kill('SIGKILL');rmSync(h.dir,{recursive:true,force:true})}
async function pointer(c,selector,match=null){const p=await c.eval(`(()=>{const xs=[...document.querySelectorAll(${q(selector)})],n=${match?`xs.find(x=>x.textContent.includes(${q(match)}))`:'xs[0]'};if(!n)return null;n.scrollIntoView({block:'center',inline:'nearest'});const r=n.getBoundingClientRect(),x=Math.max(3,Math.min(innerWidth-3,r.left+r.width/2)),y=Math.max(3,Math.min(innerHeight-3,r.top+r.height/2)),h=document.elementFromPoint(x,y);if(!h||!(h===n||n.contains(h)))return{blocked:true,rect:[r.left,r.top,r.width,r.height],hit:h?.className||h?.tagName};window.__trusted=null;n.addEventListener('click',e=>window.__trusted=e.isTrusted,{once:true,capture:true});return{x,y}})()`);assert.ok(p&&!p.blocked,JSON.stringify(p));await c.send('Input.dispatchMouseEvent',{type:'mousePressed',x:p.x,y:p.y,button:'left',buttons:1,clickCount:1,pointerType:'mouse'});await c.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:p.x,y:p.y,button:'left',buttons:0,clickCount:1,pointerType:'mouse'});await sleep(130);assert.equal(await c.eval('window.__trusted'),true)}
async function typeSearch(c,text){await pointer(c,'.switch-find-search input');await c.send('Input.dispatchKeyEvent',{type:'keyDown',key:'Control',code:'ControlLeft',windowsVirtualKeyCode:17,nativeVirtualKeyCode:17,modifiers:2});await c.send('Input.dispatchKeyEvent',{type:'keyDown',key:'a',code:'KeyA',windowsVirtualKeyCode:65,nativeVirtualKeyCode:65,modifiers:2});await c.send('Input.dispatchKeyEvent',{type:'keyUp',key:'a',code:'KeyA',windowsVirtualKeyCode:65,nativeVirtualKeyCode:65,modifiers:2});await c.send('Input.dispatchKeyEvent',{type:'keyUp',key:'Control',code:'ControlLeft',windowsVirtualKeyCode:17,nativeVirtualKeyCode:17});await c.send('Input.insertText',{text});await c.wait(`document.querySelector('.switch-find-search input')?.value===${q(text)}`,'typed')}
async function enterResults(c){await c.nav(`${BASE}?view=workspace&mode=switch`);await c.wait(`document.querySelector('.switch-find-search input')`,'search');await c.wait(`!document.body.innerText.includes('제품 목록을 불러오는 중입니다.')`,'catalog');await typeSearch(c,'AATU 연어');await c.wait(`[...document.querySelectorAll('.switch-find-result')].some(x=>x.textContent.includes('연어'))`,'result');await pointer(c,'.switch-find-result','연어');await c.wait(`document.querySelector('.switch-current-preview')`,'preview');await pointer(c,'.switch-current-preview .switch-primary-action');await c.wait(`document.querySelectorAll('.switch-sku-option').length>0`,'sku');await pointer(c,'.switch-sku-option','1 kg');await pointer(c,'.switch-step-actions .switch-primary-action');await c.wait(`document.querySelector('.switch-no-change')`,'change');await pointer(c,'.switch-no-change');await pointer(c,'.switch-step-actions .switch-primary-action');await c.wait(`document.querySelector('.switch-current-facts-strip')`,'keep');await pointer(c,'.switch-step-actions .switch-primary-action');await c.wait(`document.querySelector('.switch-results-stage')`,'results')}
async function setupFirstCandidate(c,report){for(let i=0;i<30;i++){const found=await c.eval(`[...document.querySelectorAll('.switch-candidate-row')].some(x=>x.querySelector('.switch-candidate-identity strong')?.textContent.trim()===${q(FIRST.name)})`);if(found)break;assert.equal(await c.eval(`Boolean(document.querySelector('.load-more'))`),true);await c.eval(`document.querySelector('.load-more').click()`);report.setupDomClicks++;await sleep(130)}const p=await c.eval(`(()=>{const n=[...document.querySelectorAll('.switch-candidate-row')].find(x=>x.querySelector('.switch-candidate-identity strong')?.textContent.trim()===${q(FIRST.name)});n.scrollIntoView({block:'center'});const r=n.getBoundingClientRect();window.__row=null;n.addEventListener('click',e=>window.__row=e.isTrusted,{once:true,capture:true});return{x:r.left+r.width/2,y:r.top+r.height/2}})()`);await c.send('Input.dispatchMouseEvent',{type:'mousePressed',x:p.x,y:p.y,button:'left',buttons:1,clickCount:1,pointerType:'mouse'});await c.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:p.x,y:p.y,button:'left',buttons:0,clickCount:1,pointerType:'mouse'});await sleep(130);assert.equal(await c.eval('window.__row'),true);await c.wait(`document.querySelector('.switch-candidate-inspector h1')?.textContent.trim()===${q(FIRST.name)}`,'inspector');await pointer(c,'.switch-inspector-actions .switch-compare-action','비교에 추가');await c.wait(`document.querySelector('.switch-compare-dock')`,'dock');await pointer(c,'.switch-preview-topline button');assert.equal((await c.eval(`(()=>{const r=sessionStorage.getItem(${q(STORAGE)});const s=JSON.parse(r).state;return s.currentProductId===${q(CURRENT.productId)}&&s.variantSelection.variantId===${q(CURRENT.variantId)}&&s.compareIds.includes(${q(FIRST.productId)})})()`)),true)}
async function inspect(c){return c.eval(`(()=>{const b=document.querySelector('.load-more'),d=document.querySelector('.switch-compare-dock');if(!b||!d)return null;const ownerOf=n=>{for(let p=n.parentElement;p;p=p.parentElement){const s=getComputedStyle(p);if(/auto|scroll/.test(s.overflowY)&&p.scrollHeight>p.clientHeight+1)return p}return document.scrollingElement},o=ownerOf(b),br=b.getBoundingClientRect(),dr=d.getBoundingClientRect(),x=Math.max(2,Math.min(innerWidth-2,br.left+br.width/2)),y=Math.max(2,Math.min(innerHeight-2,br.top+br.height/2)),h=document.elementFromPoint(x,y);return{buttonRect:{top:br.top,bottom:br.bottom,left:br.left,right:br.right,width:br.width,height:br.height},dockRect:{top:dr.top,bottom:dr.bottom,left:dr.left,right:dr.right,width:dr.width,height:dr.height},owner:{tag:o.tagName,className:o.className,scrollTop:o.scrollTop,scrollHeight:o.scrollHeight,clientHeight:o.clientHeight,maxScroll:o.scrollHeight-o.clientHeight},point:{x,y},hit:h?{tag:h.tagName,className:typeof h.className==='string'?h.className:'',text:h.textContent?.trim().slice(0,80)??''}:null,pointerAccessible:Boolean(h&&(h===b||b.contains(h)))}})()`)}
async function runReview(c){const initial=await inspect(c);assert.ok(initial);await c.eval(`(()=>{const b=document.querySelector('.load-more'),ownerOf=n=>{for(let p=n.parentElement;p;p=p.parentElement){const s=getComputedStyle(p);if(/auto|scroll/.test(s.overflowY)&&p.scrollHeight>p.clientHeight+1)return p}return document.scrollingElement},o=ownerOf(b);o.scrollTop=o.scrollHeight})()`);await sleep(180);const atMax=await inspect(c);if(!atMax.pointerAccessible){await c.eval(`document.querySelector('.load-more').scrollIntoView({block:'center',inline:'nearest'})`);await sleep(180)}const after=await inspect(c);await c.shot('390-load-more-dock.png');let trusted=false;if(after.pointerAccessible){await c.eval(`(()=>{const b=document.querySelector('.load-more');window.__lm=null;b.addEventListener('click',e=>window.__lm=e.isTrusted,{once:true,capture:true})})()`);await c.send('Input.dispatchMouseEvent',{type:'mousePressed',x:after.point.x,y:after.point.y,button:'left',buttons:1,clickCount:1,pointerType:'mouse'});await c.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:after.point.x,y:after.point.y,button:'left',buttons:0,clickCount:1,pointerType:'mouse'});await sleep(130);trusted=await c.eval('window.__lm');assert.equal(trusted,true)}return{initial,atMax,afterScrollIntoView:after,trustedPointer:trusted,classification:after.pointerAccessible?'qa_position_issue':'potential_product_defect',screenshot:'390-load-more-dock.png'}}
async function network(c){const writes=c.requests.filter(r=>r.url.includes('gnosbstdatkytsyxuapt.supabase.co')&&!['GET','HEAD','OPTIONS'].includes(r.method)),analytics=c.requests.filter(r=>r.url.includes('/functions/v1/decision-intake')),nonRead=c.requests.filter(r=>!['GET','HEAD','OPTIONS'].includes(r.method)),blocked=await c.eval('window.__qaBlocked');assert.equal(writes.length,0);assert.equal(analytics.length,0);assert.equal(nonRead.length,0);assert.deepEqual(blocked,{analytics:0,writes:0});return{gets:c.requests.filter(r=>r.method==='GET').length,writes:0,analytics:0,nonRead:0,blocked}}
const h=await launch(),c=h.c,report={viewport:'390x900',setupDomClicks:0,status:'running'}
try{await enterResults(c);await setupFirstCandidate(c,report);report.review=await runReview(c);report.network=await network(c);report.status='pass';writeFileSync(`${OUT}/load-more-dock-report.json`,JSON.stringify(report,null,2));console.log('LOAD_MORE_DOCK_PASS',JSON.stringify(report))}catch(e){report.status='fail';report.error=String(e?.stack??e);writeFileSync(`${OUT}/load-more-dock-report.json`,JSON.stringify(report,null,2));throw e}finally{await cleanup(h)}
